    A=(inp[:pos] if sep=='h' else [row[:pos] for row in inp]); B=(inp[pos+1:] if sep=='h' else [row[pos+1:] for row in inp])
    an={(r,c) for r,row in enumerate(A) for c,x in enumerate(row) if x!=0}
    bn={(r,c) for r,row in enumerate(B) for c,x in enumerate(row) if x!=0}
    if not an or not bn: return [[0]* (max(c for r,c in an)+1 if an else 0) for _ in range(len(A))]
    marrA=min(r for r,c in an); maccA=min(c for r,c in an)
    mrB=min(r for r,c in bn); mcB=min(c for r,c in bn)
    kept=set()
    for (r,c) in an:
        if (mrB+(r-marrA), mcB+(c-maccA)) in bn: kept.add((r,c))
    W_out=max(c for r,c in an)+1
    return [[2 if (i,j) in kept else 0 for j in range(W_out)] for i in range(len(A))]

for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    print(k, f(G[k+' input'])==G[k+' output'])
